VX={codex:"Codex",claude:"Claude Code",opencode:"OpenCode",browser:"ChatGPT / Claude web",headless:"Headless",other:"Other"};function VG(e,t){const r=new URL("/mcp/setup",e);return t&&r.searchParams.set("company",t),r.toString()}n(VG,"mcpSetupUrl");function HX(e,t){return`Connect to my ${t?`${t.name} `:""}Paperclip organization using the instructions at ${VG(e,t?.id)}. Start authorization, give me the approval link, and verify the connection after I approve.`}n(HX,"mcpInvitation");function KX(e,t){const r=`'${e.replaceAll("'",`'"'"'`)}'`,o=GG.join(" ");switch(t){case"codex":return[{text:"Check for an existing Paperclip server first. Reuse it only if its URL matches this instance. Add the remote server with the Codex CLI.",code:`codex mcp add paperclip --url ${r}`},{text:"Start browser authorization and give the user the approval link.",code:"codex mcp login paperclip --scopes paperclip:read,paperclip:write,paperclip:configure,offline_access"},{text:"If the current conversation does not reload its MCP tools, start a new conversation or restart the client. Verify the connection with paperclip_connection before claiming success."}];case"claude":return[{text:"Check existing servers and reuse a matching instance. Add the remote server using Claude Code.",code:`claude mcp add --transport http paperclip ${r}`},{text:"In Claude Code, run /mcp, select paperclip, and choose Authenticate. Versions that offer `claude mcp login --help` can also start authorization with `claude mcp login paperclip`. Give the user the approval link."},{text:"Reconnect through /mcp, or start a new session if needed. Verify the account and organization with paperclip_connection."}];case"opencode":return[{text:"Check `opencode --version` and existing configuration. For OpenCode 1.x, merge this entry into opencode.json without replacing other settings. OpenCode 2.x uses mcp.servers; use that version's documented format instead.",code:JSON.stringify({mcp:{paperclip:{type:"remote",url:e,enabled:!0,oauth:{scope:o}}}},null,2)},{text:"Run from the same project directory. OpenCode opens Paperclip's sign-in and consent page; give the user the approval link.",code:"opencode mcp auth paperclip"},{text:"If OpenCode was already running, restart it to load the connection. For the browser app, use this command. Verify the tools with paperclip_connection.",code:"opencode web"}];case"browser":return[{text:"Open your assistant's Apps / Connectors settings and add a custom remote MCP connection using this URL. Availability depends on the account and workspace policy. Reading this page in chat does not install a connector.",code:e},{text:"Choose OAuth / browser sign-in. Approve the connection in Paperclip, then select the connector in your conversation. If custom connectors are unavailable, use a supported local client. Verify the connected account and organization before doing work."}];case"headless":return[{text:"Use a Paperclip CLI version with `mcp login --device` support. This needs no callback listener; it prints a verification URL and user code, then waits for human approval.",code:`paperclipai mcp login --device --url ${r}`},{text:"After approval, configure a local stdio MCP server running the command below. Credentials stay in the CLI's private credential store. Do not copy tokens or device codes into chat or project configuration.",code:`paperclipai mcp proxy --url ${r}`},{text:"The user code is for the human to verify the request. The private device code remains inside the CLI. After connecting, call paperclip_connection to verify the account and organization."}];default:return[{text:"Add a remote HTTP MCP server at this URL, then choose OAuth / browser sign-in.",code:e},{text:"If the client cannot install MCP servers from chat, use its connection settings. If it cannot receive a browser callback, use the Headless instructions. After approval, verify the account and organization with paperclip_connection."}]}}n(KX,"mcpSetupSteps");
